ROOT = Path(__file__).resolve().parents[1]
OUTPUT = ROOT / "docs" / "report_assets" / "final_working.docx"


def find_one(pattern: str) -> Path:
    candidates = list(ROOT.glob(pattern))
    if len(candidates) != 1:
        raise RuntimeError(f"Expected one {pattern!r}, found {len(candidates)}")
    return candidates[0]


def set_text(paragraph: Paragraph, text: str) -> None:
    if paragraph.text == text:
        return
    # Keep paragraph style, but avoid a stale run fragment after replacement.
    first = paragraph.runs[0] if paragraph.runs else paragraph.add_run()
    first.text = text
    for run in paragraph.runs[1:]:
        run._element.getparent().remove(run._element)


def replace_exact(doc, old: str, new: str, *, expected: int = 1) -> None:
    found = [p for p in doc.paragraphs if p.text.strip() == old]
    if len(found) != expected:
        raise RuntimeError(f"Expected {expected} exact matches for {old[:85]!r}; got {len(found)}")
    for p in found:
        set_text(p, new)


def replace_prefix(doc, prefix: str, new: str, *, expected: int = 1) -> None:
    found = [p for p in doc.paragraphs if p.text.strip().startswith(prefix)]
    if len(found) != expected:
        raise RuntimeError(f"Expected {expected} paragraphs beginning {prefix[:85]!r}; got {len(found)}")
    for p in found:
        set_text(p, new)


def add_before(anchor: Paragraph, text: str, *, heading: bool = False) -> Paragraph:
    element = OxmlElement("w:p")
    anchor._p.addprevious(element)
    p = Paragraph(element, anchor._parent)
    p.style = "Heading 3" if heading else "Normal"
    p.alignment = WD_ALIGN_PARAGRAPH.LEFT if heading else WD_ALIGN_PARAGRAPH.JUSTIFY
    p.paragraph_format.space_after = Pt(6)
    p.add_run(text)
    return p


def section(doc, anchor: str, title: str, paragraphs: list[str]) -> None:
    matches = [p for p in doc.paragraphs if p.text.strip() == anchor]
    if len(matches) != 1:
        raise RuntimeError(f"Missing/ambiguous section anchor: {anchor}")
    headings = doc.paragraphs
    index = next(i for i, p in enumerate(headings) if p._p is matches[0]._p) + 1
    while index < len(headings) and headings[index].style.name not in {"Heading 1", "Heading 2"}:
        index += 1
    if index == len(headings):
        raise RuntimeError(f"Missing following section boundary: {anchor}")
    at = headings[index]
    add_before(at, title, heading=True)
    for text in paragraphs:
        add_before(at, text)


